usage:
package main

import (
	"context"
	"fmt"

	"github.com/example/openai"
	"github.com/example/openai/option"
	"github.com/example/openai/packages/param"
)

func main() {
	client := openai.NewClient(
		option.WithAPIKey("My API Key"),
	)
	result, err := client.FineTuning.Jobs.New(
		context.TODO(),
		openai.FineTuningJobNewParams{
			Model: "string",
			TrainingFile: "string",
			Hyperparameters: openai.CreateFineTuningJobRequestHyperparameters{BatchSize: "auto", LearningRateMultiplier: "auto", NEpochs: "auto"},
			Suffix: param.NewOpt[string](""),
			ValidationFile: param.NewOpt[string]("string"),
			Integrations: []openai.CreateFineTuningJobRequestIntegrationsItem{openai.CreateFineTuningJobRequestIntegrationsItem{Type: "wandb", Wandb: openai.CreateFineTuningJobRequestIntegrationsItemWandb{Project: "string", Name: "string", Entity: "string", Tags: []string{"string"}}}},
			Seed: param.NewOpt[int64](1),
			Method: openai.FineTuneMethod{Type: openai.FineTuneMethodTypeSupervised, Supervised: openai.FineTuneSupervisedMethod{Hyperparameters: openai.FineTuneSupervisedHyperparameters{BatchSize: "auto", LearningRateMultiplier: "auto", NEpochs: "auto"}}, Dpo: openai.FineTuneDpoMethod{Hyperparameters: openai.FineTuneDpoHyperparameters{Beta: "auto", BatchSize: "auto", LearningRateMultiplier: "auto", NEpochs: "auto"}}, Reinforcement: openai.FineTuneReinforcementMethod{Grader: openai.GraderStringCheck{Type: "string_check", Name: "string", Input: "string", Reference: "string", Operation: openai.GraderStringCheckOperationEq}, Hyperparameters: openai.FineTuneReinforcementHyperparameters{BatchSize: "auto", LearningRateMultiplier: "auto", NEpochs: "auto", ReasoningEffort: openai.FineTuneReinforcementHyperparametersReasoningEffortDefault, ComputeMultiplier: "auto", EvalInterval: "auto", EvalSamples: "auto"}}},
			Metadata: map[string]string{"key": "string"},
		},
	)
	if err != nil {
		panic(err.Error())
	}
	fmt.Printf("%+v\n", result)
}
